def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    last_my, last_opp = history[-1]
    opp_c = 0
    opp_d = 0
    for h in history:
        if h[1] == 'C':
            opp_c += 1
        else:
            opp_d += 1
    if opp_d == 0:
        return 'C'
    if opp_d / n > 0.8 and n > 10:
        return 'D'
    if last_opp == 'D':
        if opp_c == 0:
            return 'D'
        if last_my == 'D':
            return 'C'
        else:
            if n >= 2 and history[-2][0] == 'D':
                return 'C'
            else:
                return 'D'
    else:
        return 'C'
